from h import *
A = dict(id="A", levels=L1, kind="Notice", source="Ashby Green Parish Council", title="Have your say on new homes in Ashby Green", body=[
 {"p": "Ashby Green Parish Council is holding a meeting about plans to build 40 new homes in the village. Everyone is welcome."},
 {"p": "There are three ways to have your say:"},
 {"ol": ["Come to the meeting at the village hall on Thursday at 7:30 pm.", "Write to the Parish Clerk at the village hall.", "Fill in the short form on the council website."]},
 {"p": "Please tell us what you think before the end of the month."}])
B = dict(id="B", levels=L1, kind="Information leaflet", source="Ashby Green Parish Council", title="New homes for Ashby Green: the facts", body=[
 {"p": "Ashby Green Parish Council has been asked to approve plans for 40 new homes on a field beside Church Lane. About 1,200 people live in the village today. This leaflet sets out the main facts so that residents can decide what they think."},
 {"h": "Why build here?"},
 {"p": "There are two main reasons for the plan: the village school has empty places, and the village shop is struggling to stay open. The council hopes that new families will help to keep both going. Over the last ten years, the number of children at the school has fallen and two other shops have closed. Councillor Ruth Barnes says, \"The new homes will bring the village back to life.\""},
 {"h": "What kind of homes?"},
 {"p": "Twenty-four of the homes will be for sale on the open market, with between two and four bedrooms. Sixteen will be affordable homes, which cost less to buy or rent than most houses in the area. These will be offered first to people who already live or work in the village. All of the new homes will have gardens and parking spaces, and they will be built to use less energy than older houses."},
 {"h": "What are the worries?"},
 {"p": "Not everyone is in favour. Some residents are worried about extra traffic on the narrow lanes. One resident, Tom Hendry, says, \"The lanes simply cannot cope with more traffic.\" Others do not want to lose the field, which is used by dog walkers and for the summer fair. The developer says it will pay for a new bus shelter and a safer crossing on Church Lane."},
 {"h": "What happens next?"},
 {"p": "The parish council will meet on Thursday to hear residents' views. The plans must then be approved by the district council, which will decide whether to grant planning permission. A decision is expected within six months."}])
C = dict(id="C", levels=L1, kind="Letter", source="Letter to Ashby Green Parish Council", title="Letter about the Church Lane homes", body=[
 {"p": "Dear Councillors,"},
 {"p": "I am writing to say that I support the plan to build new homes on Church Lane. I am 19 and I have lived in Ashby Green all my life, but I doubt that I will be able to stay here. Even a small flat in the village costs far more than I can afford on my wage from the garden centre."},
 {"p": "Several of my friends have already moved to Brayminster, where there are more homes to rent and the bus runs every fifteen minutes. If the village does not build homes for young people, it will soon have no young people left. I know that some neighbours are worried about traffic, and I understand why. However, I believe a few more cars are a small price to pay for a village that stays alive."},
 {"p": "I would therefore ask the council to:"},
 {"ul": ["make sure the affordable homes go to local people first", "keep a footpath through the field so that walkers can still use it", "ask the bus company to run buses more often, as more people will need them"]},
 {"p": "I would be grateful if you would consider my views at Thursday's meeting."},
 {"p": "Yours faithfully,"},
 {"p": "A resident of Ashby Green"}])

